N = int(input())
a = list(map(int, input().split()))
table = collections.defaultdict(int)

for i in range(1, N):
    table[a[i]] += 1

ans = [-1] * N
ans[0] = a[0]

for i in range(1, N):
    x = a[0] ^ a[i]
    if x in table and table[x] >= 1:
        if a[0] == 0 and x == 0 and table[a[i]] == 1:
            continue
        ans[1] = x
        ans[2] = a[i]
        table[ans[1]] -= 1
        table[ans[2]] -= 1
        break

if ans[1] == -1:
    print("No")
    exit(0)

for i in range(3, N):
    x = ans[i - 1] ^ ans[i - 2]
    if x in table and table[x] >= 1:
        ans[i] = x
        table[ans[i]] -= 1
    else:
        print("No")
        exit(0)

if ans[N - 1] ^ ans[0] == ans[N - 2]:
    print("Yes")
else:
    print("No")

