import collections
def main():
    n = int(input())
    a = list(map(int,input().split()))
    cnt = collections.Counter(a)
    if set(a) == {0}:
        print('Yes')
        return

    flag = 0
    if n % 3 == 0:
        if len(cnt) == 2:
            if cnt.get(0) == n // 3:
                flag = 1
